async function openReceipt(id){var dl=accountDocument(id),doc=dl&&dl.documents;if(!doc)return window.toast('Receipt is not available');if(doc.external_url)return openExternalDocument(id,doc.external_url);return openDocument(id);}
async function ackStatement(id){if(!confirm('Mark this statement as reviewed? This only confirms you viewed it and does not waive any dispute.'))return;try{await VEUX_MODEL.api('/api/model/account-action',{method:'POST',body:JSON.stringify({organization_slug:'maison-de-veux',action:'acknowledge_statement',statement_id:id})});window.toast('Statement marked reviewed');await VEUX_MODEL.refresh();}catch(e){window.toast('Could not mark statement reviewed: '+(e.message||e));}}

function compCards(){return arr(boot().documents).map(function(link){var d=link.documents||link.document||link;return {link:link,doc:d};}).filter(function(x){var d=x.doc||{},l=x.link||{},hay=[d.category,d.name,d.title,l.relationship,l.category].join(' ').toLowerCase();return /comp[\s_-]*card|composite/.test(hay)&&String(d.status||'active').toLowerCase()!=='archived';}).sort(function(a,b){return new Date((b.doc||{}).updated_at||(b.doc||{}).created_at||(b.link||{}).created_at||0)-new Date((a.doc||{}).updated_at||(a.doc||{}).created_at||(a.link||{}).created_at||0);});}
function compMarket(x){var d=x.doc||{},l=x.link||{},meta=d.metadata||{},v=String(meta.market||l.market||l.relationship||'').toLowerCase();if(/paris|\bfr\b|france/.test(v))return 'Paris';if(/new[\s_-]*york|\bny\b|usa/.test(v))return 'New York';return meta.market||'Agency';}
function compDate(x){var d=x.doc||{},v=d.updated_at||d.created_at||(x.link||{}).created_at;if(!v)return 'Current edition';try{return 'Updated '+new Date(v).toLocaleDateString([],{month:'short',day:'numeric',year:'numeric'});}catch(_e){return 'Current edition';}}
async function downloadCompCard(id,name){try{var r=await VEUX_MODEL.api('/api/storage/download-url?document_id='+encodeURIComponent(id),{method:'GET'});if(!r.url)throw new Error('Comp card is unavailable');var res=await fetch(r.url,{credentials:'omit'});if(!res.ok)throw new Error('Comp card download failed');var blob=await res.blob(),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=(String(name||modelName()+'-Comp-Card.pdf').replace(/[^a-z0-9._-]+/gi,'-'));if(!/\.[a-z0-9]{2,5}$/i.test(a.download))a.download+='.pdf';document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(u);},1500);await VEUX_MODEL.acknowledge('document',id).catch(function(){});}catch(e){window.toast('Comp card could not download: '+(e.message||e));}}
function renderCompCards(){var a=compCards();if(!a.length)return card('Official Comp Card','<div class="v16962-comp-empty"><b>Agency comp card not published yet.</b><span>Your official agency-approved comp card will appear here automatically when it is released to your profile.</span></div>','Agency managed');return card('Official Comp Card','<div class="v16962-comp-grid">'+a.map(function(x,i){var d=x.doc||{},market=compMarket(x),current=i===0||d.metadata&&d.metadata.current===true;return '<article class="v16962-comp-card"><div class="v16962-comp-preview"><div class="v16962-comp-mark">CAVYRE</div><strong>'+esc(modelName())+'</strong><span>'+esc(market)+' · COMP CARD</span><em>PDF</em></div><div class="v16962-comp-info"><div><small>'+(current?'CURRENT · ':'')+esc(market.toUpperCase())+'</small><h3>'+esc(d.name||modelName()+' Comp Card')+'</h3><p>'+esc(compDate(x))+'</p></div><div class="v16962-comp-actions"><button class="v15m-mini-btn" onclick="VEUX_MODEL_V15.openDocument(\''+d.id+'\')">View Comp Card</button><button class="v15m-btn gold" onclick="VEUX_MODEL_V15.downloadCompCard(\''+d.id+'\',\''+esc(d.name||modelName()+'-Comp-Card.pdf')+'\')">Download PDF</button></div></div></article>';}).join('')+'</div>','Agency approved · '+a.length+' available');}

