 var archive=a.length>1?card('Previous / Market Versions','<div class="v16966-comp-list">'+a.slice(1).map(function(x){var d=x.doc||{},market=compMarket(x),name=d.name||modelName()+' Comp Card';return '<article><div><small>'+esc(market.toUpperCase())+'</small><b>'+esc(name)+'</b><span>'+esc(compDate(x))+'</span></div><div><button class="v15m-mini-btn" onclick="VEUX_MODEL_V15.openDocument(\''+d.id+'\')">View</button><button class="v15m-mini-btn" onclick="VEUX_MODEL_V15.downloadCompCard(\''+d.id+'\',\''+esc(name)+'\')">Download</button></div></article>';}).join('')+'</div>',(a.length-1)+' additional'):'';
 el.innerHTML='<div class="v15m-page">'+pageHead('MODEL TOOLS · AGENCY ASSETS','Comp Card','View and download the official comp card released to your model profile.')+hero+selfServe+archive+'</div>';
