function renderProfile(el){var x=m(),p=x.private_profile||{},mm=x.measurement||{},ec=p.emergency_contact||{};el.innerHTML='<div class="v15m-page">'+pageHead('PROFILE · SELF SERVICE','My Profile','Review agency-facing measurements and update approved contact fields.',btn('Save Contact Details','VEUX_MODEL_V15.saveProfile()',true))+hero()+renderPortalExchangeStatus()+renderCompCards()+'<div class="v15m-grid two v15m-section-gap">'+card('Contact Details','<div class="v15m-form"><label>Phone<input class="v15m-input" id="v15m-phone" value="'+esc(p.phone||'')+'"></label><label>WhatsApp<input class="v15m-input" id="v15m-wa" value="'+esc(p.whatsapp||'')+'"></label><label>Instagram<input class="v15m-input" id="v15m-ig" value="'+esc(p.instagram||'')+'"></label><label>Email<input class="v15m-input" value="'+esc(p.email||'')+'" disabled></label></div>','Editable')+card('Emergency Contact','<div class="v15m-form"><label>Name<input class="v15m-input" id="v15m-ec-name" value="'+esc(ec.name||'')+'"></label><label>Relationship<input class="v15m-input" id="v15m-ec-rel" value="'+esc(ec.relationship||'')+'"></label><label>Phone<input class="v15m-input" id="v15m-ec-phone" value="'+esc(ec.phone||'')+'"></label><label>Email<input class="v15m-input" id="v15m-ec-email" value="'+esc(ec.email||'')+'"></label></div>','Private · Agency only')+'</div>'+card('Measurements',[['Height',mm.height_display||mm.height],['Bust / Chest',mm.bust||mm.chest],['Waist',mm.waist],['Hips',mm.hips],['Shoe',mm.shoe],['Hair',mm.hair],['Eyes',mm.eyes]].filter(function(z){return z[1];}).map(function(z){return '<div class="v15m-row"><div><h3>'+esc(z[0])+'</h3></div><strong>'+esc(z[1])+'</strong></div>';}).join('')||empty('No measurements are currently on file.'),'Agency managed')+'</div>';}
async function saveProfile(){try{await VEUX_MODEL.updateProfile({phone:(document.getElementById('v15m-phone')||{}).value||'',whatsapp:(document.getElementById('v15m-wa')||{}).value||'',instagram:(document.getElementById('v15m-ig')||{}).value||'',emergency_contact:{name:(document.getElementById('v15m-ec-name')||{}).value||'',relationship:(document.getElementById('v15m-ec-rel')||{}).value||'',phone:(document.getElementById('v15m-ec-phone')||{}).value||'',email:(document.getElementById('v15m-ec-email')||{}).value||''}});window.toast('Profile updated');await VEUX_MODEL.refresh();}catch(e){window.toast('Profile update failed: '+(e.message||e));}}
function modal(title,body,actions){var old=document.getElementById('v16m-modal');if(old)old.remove();var bg=document.createElement('div');bg.id='v16m-modal';bg.className='v16m-modal-bg';bg.innerHTML='<div class="v16m-modal"><header><div><small>VEUX DESK</small><h2>'+esc(title)+'</h2></div><button onclick="VEUX_MODEL_V15.closeModal()">×</button></header><div class="v16m-modal-body">'+body+'</div><footer>'+(actions||'')+'</footer><div class="v16m-modal-error" id="v16m-modal-error"></div></div>';bg.addEventListener('click',function(e){if(e.target===bg)bg.remove();});document.body.appendChild(bg);}
function closeModal(){var x=document.getElementById('v16m-modal');if(x)x.remove();}
function openBookout(){var now=new Date(),later=new Date(now.getTime()+86400000);function iso(d){var z=new Date(d.getTime()-d.getTimezoneOffset()*60000);return z.toISOString().slice(0,16);}modal('Request Bookout / Availability','<div class="v16m-form"><label>Type<select id="v16m-bo-type"><option value="bookout">Bookout</option><option value="unavailable">Unavailable</option><option value="travel">Travel</option><option value="personal">Personal</option><option value="school">School</option></select></label><label>Starts<input id="v16m-bo-start" type="datetime-local" value="'+iso(now)+'"></label><label>Ends<input id="v16m-bo-end" type="datetime-local" value="'+iso(later)+'"></label><label class="full">Reason<textarea id="v16m-bo-reason" rows="4" placeholder="Give the agency enough context to review the request."></textarea></label></div>','<button class="v15m-btn" onclick="VEUX_MODEL_V15.closeModal()">Cancel</button><button class="v15m-btn gold" onclick="VEUX_MODEL_V15.submitBookout()">Send Request</button>');}
async function submitBookout(){var start=(document.getElementById('v16m-bo-start')||{}).value,end=(document.getElementById('v16m-bo-end')||{}).value;if(!start||!end)return;try{await VEUX_MODEL.requestAvailability({request_type:(document.getElementById('v16m-bo-type')||{}).value||'bookout',starts_at:new Date(start).toISOString(),ends_at:new Date(end).toISOString(),timezone:Intl.DateTimeFormat().resolvedOptions().timeZone||null,reason:(document.getElementById('v16m-bo-reason')||{}).value||''});closeModal();window.toast('Availability request sent');await VEUX_MODEL.refresh();}catch(e){var er=document.getElementById('v16m-modal-error');if(er)er.textContent=e.message||e;}}
