async function openDocument(id){try{var r=await VEUX_MODEL.api('/api/storage/download-url?document_id='+encodeURIComponent(id),{method:'GET'});if(!r.url)throw new Error('Document is unavailable');window.open(r.url,'_blank','noopener');await VEUX_MODEL.acknowledge('document',id).catch(function(){});await VEUX_MODEL.refresh();}catch(e){window.toast('Document could not open: '+(e.message||e));}}
