function syncNotificationBadge(){var n=arr(boot().notifications).filter(function(x){return !x.read_at;}).length,b=document.getElementById('tbNotifyCount');if(b){b.textContent=n>99?'99+':String(n);b.classList.toggle('show',n>0);}}
function renderNotifications(el){var n=arr(boot().notifications),unread=n.filter(function(x){return !x.read_at;});el.innerHTML='<div class="v15m-page">'+pageHead('UPDATES · MODEL DESK','Updates','Agency notifications, deadlines and portal alerts.',unread.length?btn('Mark All Read','VEUX_MODEL_V15.markAllNotifications()',true):'')+card('Notifications',n.map(function(x){return '<button class="v16m-notification '+(!x.read_at?'unread':'')+'" onclick="VEUX_MODEL_V15.markNotification(\''+x.id+'\')"><div><small>'+esc(fmtDate(x.created_at))+' '+esc(fmtTime(x.created_at))+'</small><h3>'+esc(x.title||'Agency Update')+'</h3><p>'+esc(x.body||x.message||'')+'</p></div>'+(!x.read_at?status('New'):status('Read'))+'</button>';}).join('')||empty('No notifications yet.'),unread.length+' unread · '+n.length+' total')+'</div>';}
