var MODEL_MESSAGE_ALERT_KEY='veux-model-last-message-alert-v1',modelMessagePollTimer=null;
function modelIsMessageNotification(x){return !!x&&!x.read_at&&(String(x.source_type||'')==='conversation'||/message/i.test(String(x.notification_type||'')));}
function closeModelMessageAlert(){var el=document.getElementById('v16-message-alert');if(el)el.remove();}
function openModelMessageAlert(x){closeModelMessageAlert();var conversationId=x&&x.metadata&&x.metadata.conversation_id||x&&x.source_id||'';if(x&&x.id&&window.VEUX_MODEL&&VEUX_MODEL.readNotification){VEUX_MODEL.readNotification(x.id).catch(function(){});x.read_at=new Date().toISOString();syncNotificationBadge();}if(conversationId){S.thread=conversationId;navTo('inbox');}}
function showModelMessageAlert(x){if(!x||!x.id)return;var last='';try{last=sessionStorage.getItem(MODEL_MESSAGE_ALERT_KEY)||'';}catch(_e){}if(last===String(x.id))return;try{sessionStorage.setItem(MODEL_MESSAGE_ALERT_KEY,String(x.id));}catch(_e){}closeModelMessageAlert();var el=document.createElement('div');el.id='v16-message-alert';el.className='v16-message-alert';el.setAttribute('role','status');el.innerHTML='<span class="v16-message-dot"></span><div><b>'+esc(x.title||'New agency message')+'</b><p>'+esc(x.body||'Open Messages to view the conversation.')+'</p></div><button class="primary" type="button">Open Messages</button><button class="close" type="button" aria-label="Dismiss">×</button>';var buttons=el.querySelectorAll('button');buttons[0].onclick=function(){openModelMessageAlert(x);};buttons[1].onclick=closeModelMessageAlert;document.body.appendChild(el);}
async function pollModelMessageAlerts(){if(document.visibilityState&&document.visibilityState==='hidden')return;try{var d=await VEUX_MODEL.api('/api/portal/notifications?portal=model&organization=maison-de-veux',{method:'GET'}),n=arr(d.notifications),b=boot();b.notifications=n;syncNotificationBadge();var msg=n.find(modelIsMessageNotification);if(msg)showModelMessageAlert(msg);}catch(_e){}}
function installModelMessageAlerts(){if(modelMessagePollTimer)return;setTimeout(pollModelMessageAlerts,1000);function cycle(){pollModelMessageAlerts();modelMessagePollTimer=setTimeout(cycle,30000);}modelMessagePollTimer=setTimeout(cycle,30000);window.addEventListener('focus',pollModelMessageAlerts);document.addEventListener('visibilitychange',function(){if(document.visibilityState==='visible')pollModelMessageAlerts();});}
function initAssistantWidget(){if(document.getElementById('_v16m-ai'))return;var history=[],open=false,b=document.createElement('button');b.id='_v16m-ai';b.className='v16m-ai-btn';b.textContent='✦';b.title='VEUX Intelligence';document.body.appendChild(b);var p=document.createElement('section');p.id='_v16m-ai-panel';p.className='v16m-ai-panel';p.innerHTML='<header><div><small>VEUX DESK</small><b>Model Intelligence</b></div><button id="_v16m-ai-close">×</button></header><div id="_v16m-ai-msgs" class="v16m-ai-msgs"></div><footer><input id="_v16m-ai-input" placeholder="Ask about your schedule, travel or agency workflow…"><button id="_v16m-ai-send">Send</button></footer>';document.body.appendChild(p);function toggle(){open=!open;p.classList.toggle('open',open);}function add(role,text){var d=document.createElement('div');d.className='v16m-ai-msg '+role;d.innerHTML='<small>'+(role==='user'?'You':'VEUX')+'</small><p>'+esc(text)+'</p>';document.getElementById('_v16m-ai-msgs').appendChild(d);d.parentNode.scrollTop=d.parentNode.scrollHeight;}async function send(){var i=document.getElementById('_v16m-ai-input'),msg=(i.value||'').trim();if(!msg)return;i.value='';add('user',msg);history.push({role:'user',content:msg});try{var r=await VEUX_MODEL.api('/ask-claude',{method:'POST',body:JSON.stringify({message:msg,history:history.slice(-10),context:{page:S.page}})});add('assistant',r.reply||r.message||'No response generated.');history.push({role:'assistant',content:r.reply||r.message||''});}catch(e){add('assistant','I could not complete that request: '+(e.message||e));}}b.onclick=toggle;document.getElementById('_v16m-ai-close').onclick=toggle;document.getElementById('_v16m-ai-send').onclick=send;document.getElementById('_v16m-ai-input').addEventListener('keydown',function(e){if(e.key==='Enter')send();});add('assistant','I can help explain your schedule, tasks, travel, documents and portal workflow.');}
function renderInbox(el){var b=boot(),convs=arr(b.conversations),msgs=arr(b.messages);if(!S.thread&&convs[0])S.thread=convs[0].id;var sel=convs.find(function(c){return c.id===S.thread;})||convs[0],threadMsgs=sel?msgs.filter(function(x){return x.conversation_id===sel.id;}):[];el.innerHTML='<div class="v15m-page">'+pageHead('COMMUNICATIONS · SECURE','Messages','Direct conversations shared between you and the agency.')+'<section class="v15m-card flush"><div class="v15m-thread-layout"><aside class="v15m-threads">'+convs.map(function(c){var last=msgs.filter(function(x){return x.conversation_id===c.id;}).slice(-1)[0]||{};return '<button class="v15m-thread '+(sel&&sel.id===c.id?'on':'')+'" onclick="VEUX_MODEL_V15.thread(\''+c.id+'\')"><b>'+esc(c.subject||'Agency Conversation')+'</b><span>'+esc((last.body||'No messages yet').slice(0,72))+'</span></button>';}).join('')+(convs.length?'':empty('No conversations yet.'))+'</aside><div class="v15m-chat">'+(sel?'<div class="v15m-card-head" style="padding:14px 16px;margin:0;border-bottom:1px solid var(--v15-line)"><b>'+esc(sel.subject||'Conversation')+'</b>'+status(sel.status)+'</div><div class="v15m-chat-scroll">'+threadMsgs.map(function(x){return '<div class="v15m-bubble '+(x.sender_user_id===b.current_user.id?'mine':'')+'"><small>'+esc(x.sender_label||'Agency')+' · '+esc(fmtDate(x.sent_at))+' '+esc(fmtTime(x.sent_at))+'</small><p>'+esc(x.body||'')+'</p></div>';}).join('')+'</div><div class="v15m-compose"><textarea id="v15m-reply" rows="2" placeholder="Write a reply…"></textarea><button class="v15m-btn gold" onclick="VEUX_MODEL_V15.reply(\''+sel.id+'\')">Send</button></div>':empty('Select a conversation.') )+'</div></div></section></div>';}
async function reply(id){var ta=document.getElementById('v15m-reply'),body=(ta&&ta.value||'').trim();if(!body)return window.toast('Write a reply first');try{await VEUX_MODEL.api('/api/portal/message',{method:'POST',body:JSON.stringify({portal:'model',organization_slug:'maison-de-veux',conversation_id:id,body:body})});window.toast('Message sent');await VEUX_MODEL.refresh();}catch(e){window.toast('Message failed: '+(e.message||e));}}
