function renderWellness(el){var w=boot().wellness||{},p=w.profile||{},items=arr(w.items),checks=arr(w.checkins),last=checks[0]||{},groups={};items.forEach(function(x){(groups[x.category]||(groups[x.category]=[])).push(x);});var plan=Object.keys(groups).map(function(k){return card(wellnessCategoryLabel(k),groups[k].map(function(x){return '<div class="v15m-plan-block"><h3>'+esc(x.title||'Plan item')+'</h3><p>'+esc(x.instruction||'')+'</p><ul class="v15m-plan-list">'+([x.cadence&&['Cadence',x.cadence],x.day_of_week!=null&&['Day',['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][x.day_of_week]],x.time_local&&['Time',String(x.time_local).slice(0,5)]].filter(Boolean).map(function(y){return '<li><small>'+esc(y[0])+'</small><span>'+esc(y[1])+'</span></li>';}).join(''))+'</ul></div>';}).join(''),groups[k].length+' items');}).join('')||card('Agency Wellness Plan',empty('No wellness or readiness plan has been assigned yet.'),'Relational plan');var recent=checks.slice(0,7).map(function(x){return '<div class="v15m-row"><div><small>'+esc(fmtDate(x.checkin_on))+'</small><h3>Readiness '+esc(x.readiness_rating||'—')+' / 5</h3><p>'+esc([x.routine_completion!=null?(x.routine_completion+'% routine'):null,x.hydration_liters!=null?(x.hydration_liters+'L hydration'):null,x.note].filter(Boolean).join(' · '))+'</p></div>'+status('Submitted')+'</div>';}).join('')||empty('No check-ins submitted yet.');el.innerHTML='<div class="v15m-page">'+pageHead('WELLNESS · READINESS','Wellness','Agency-assigned self-care and readiness plan with your own lightweight check-ins.')+'<div class="v15m-grid kpis">'+kpi(p.skin_routine_type||'—','Skin Routine','Agency plan')+kpi(p.fitness_goal||'—','Fitness Goal','Development')+kpi(p.hydration_goal_liters!=null?p.hydration_goal_liters+'L':'—','Hydration Goal','Daily')+kpi(last.readiness_rating?last.readiness_rating+'/5':'—','Latest Readiness',last.checkin_on?fmtDate(last.checkin_on):'No check-in')+'</div>'+(p.agency_note?'<section class="v15m-card v15m-section-gap"><div class="v15m-card-head"><b>Agency Note</b><span>Wellness</span></div><p style="margin:0;color:var(--v15-muted);font-size:12px;line-height:1.6">'+esc(p.agency_note)+'</p></section>':'')+'<div class="v15m-wellness-grid v15m-section-gap"><div>'+plan+'</div><div>'+card('Today’s Check-In','<div class="v15m-checkin"><label>Readiness<select id="v15m-w-ready"><option value="">Select…</option><option value="5">5 · Ready</option><option value="4">4 · Good</option><option value="3">3 · Okay</option><option value="2">2 · Low</option><option value="1">1 · Needs attention</option></select></label><label>Routine Completion %<input id="v15m-w-complete" type="number" min="0" max="100" step="5" placeholder="0–100"></label><label>Hydration Liters<input id="v15m-w-water" type="number" min="0" max="20" step="0.1" placeholder="0.0"></label><label>Skin Treatment<select id="v15m-w-skin"><option value="">Select…</option><option value="completed">Completed full routine</option><option value="partial">Partial routine</option><option value="skipped">Skipped today</option><option value="flare_up">Flare-up / needs attention</option></select></label><label>Note<textarea id="v15m-w-note" rows="4" placeholder="Anything the agency should know about your readiness today"></textarea></label><button class="v15m-btn gold" onclick="VEUX_MODEL_V15.wellnessCheckin()">Submit Check-In</button></div>','Model self-service')+card('Recent Check-Ins',recent,'Last 7')+'</div></div></div>';}
async function wellnessCheckin(){var ready=(document.getElementById('v15m-w-ready')||{}).value,complete=(document.getElementById('v15m-w-complete')||{}).value,water=(document.getElementById('v15m-w-water')||{}).value,skin=(document.getElementById('v15m-w-skin')||{}).value,note=(document.getElementById('v15m-w-note')||{}).value||'';if(!ready&&!complete&&!water&&!skin&&!note.trim())return window.toast('Add at least one check-in detail');try{await VEUX_MODEL.wellnessCheckIn({readiness_rating:ready||null,routine_completion:complete||null,hydration_liters:water||null,skin_treatment:skin||null,note:note});window.toast('Wellness check-in saved');await VEUX_MODEL.refresh();}catch(e){window.toast('Check-in failed: '+(e.message||e));}}

