function devSubmissionFile(f){var mime=String(f.mime_type||''),url=f.url||'';if(/^image\//i.test(mime)&&url)return '<figure class="v1699-sub-file image"><img src="'+esc(url)+'" alt=""><figcaption>'+esc(f.relationship||f.name||'Skin photo')+'</figcaption></figure>';if(/^video\//i.test(mime)&&url)return '<figure class="v1699-sub-file video"><video src="'+esc(url)+'" controls playsinline preload="metadata"></video><figcaption>'+esc(f.name||'Model walk')+'</figcaption></figure>';return '<div class="v1699-sub-file generic"><b>'+esc(f.name||'Submission file')+'</b><small>'+esc(f.mime_type||'File')+'</small></div>';}
async function renderDevelopmentSubmissions(el){
 el.innerHTML='<div class="v15m-page">'+pageHead('DEVELOPMENT · MODEL SUBMISSIONS','Skin & Walks','Send current skin checks and model walk videos directly to your development team.')+'<div class="v15m-empty">Loading your submissions…</div></div>';
 try{
  var d=await VEUX_MODEL.api('/api/model/development-submissions?organization=maison-de-veux',{method:'GET'}),subs=arr(d.submissions),skin=subs.filter(function(x){return x.submission_type==='skin';}),walk=subs.filter(function(x){return x.submission_type==='walk';});
  function historyCard(x){var files=arr(x.files),open=['pending','changes_requested'].includes(String(x.status));return '<article class="v1699-sub-history-card"><header><div><small>'+esc(x.submission_type==='skin'?'SKIN CHECK':'MODEL WALK')+'</small><h3>'+esc(fmtDate(x.submitted_on||x.created_at))+'</h3></div>'+devSubmissionStatus(x.status)+'</header>'+(x.model_note?'<p class="v1699-sub-note"><b>Your note</b>'+esc(x.model_note)+'</p>':'')+(x.agent_note?'<p class="v1699-sub-note agent"><b>Agency note</b>'+esc(x.agent_note)+'</p>':'')+'<div class="v1699-sub-files">'+files.map(devSubmissionFile).join('')+'</div>'+(open?'<footer><button class="v15m-btn" onclick="VEUX_MODEL_V15.withdrawDevelopment(\''+esc(x.id)+'\')">Withdraw</button></footer>':'')+'</article>';}
  var compose='<div class="v1699-sub-compose"><section class="v15m-card"><div class="v15m-card-head"><b>Skin Submission</b><span>Development review</span></div><div class="v1699-sub-instructions"><strong>Current skin check</strong><p>Use clean natural light, no filter, minimal/no makeup. Front, left/right profile and close-up are recommended.</p></div><label class="v1699-file-pick"><span>Choose Skin Photos</span><input id="v1699-skin-files" type="file" accept="image/jpeg,image/png,image/webp" multiple><em>JPG, PNG or WebP · up to 15 MB each</em></label><label class="v1699-sub-field"><span>Notes</span><textarea id="v1699-skin-note" rows="4" placeholder="Anything the development team should know about your skin right now"></textarea></label><button id="v1699-skin-submit" class="v15m-btn gold" onclick="VEUX_MODEL_V15.submitDevelopment(\'skin\')">Submit Skin Check</button></section><section class="v15m-card"><div class="v15m-card-head"><b>Model Walk Submission</b><span>Runway review</span></div><div class="v1699-sub-instructions"><strong>Current runway walk</strong><p>Upload a recent full-body walk video. Keep the camera stable and show the full walk, turn and return.</p></div><label class="v1699-file-pick"><span>Choose Walk Video</span><input id="v1699-walk-files" type="file" accept="video/mp4,video/quicktime" multiple><em>MP4 or MOV · up to 200 MB each</em></label><label class="v1699-sub-field"><span>Notes</span><textarea id="v1699-walk-note" rows="4" placeholder="Shoes, training focus, or anything you want the agency to review"></textarea></label><button id="v1699-walk-submit" class="v15m-btn gold" onclick="VEUX_MODEL_V15.submitDevelopment(\'walk\')">Submit Model Walk</button></section></div>';
  el.innerHTML='<div class="v15m-page">'+pageHead('DEVELOPMENT · MODEL SUBMISSIONS','Skin & Walks','Send current skin checks and model walk videos directly to your development team.',btn('Refresh','navTo(\'submissions\')'))+'<div class="v15m-grid kpis">'+kpi(skin.length,'Skin Checks','Submitted')+kpi(walk.length,'Walks','Submitted')+kpi(subs.filter(function(x){return x.status==='pending';}).length,'Pending','Agency review')+kpi(subs.filter(function(x){return x.status==='changes_requested';}).length,'Needs Changes','Agency notes')+'</div>'+compose+card('Submission History','<div class="v1699-sub-history">'+(subs.map(historyCard).join('')||empty('No skin or walk submissions yet.'))+'</div>',subs.length+' total')+'</div>';
 }catch(e){el.innerHTML='<div class="v15m-page">'+pageHead('DEVELOPMENT · MODEL SUBMISSIONS','Skin & Walks','Submit current development media to the agency.')+'<div class="v15m-empty">'+esc(e.message||e)+'</div></div>';}
}
async function uploadDevelopmentFile(submissionId,type,file,index){
 var roles=type==='skin'?['front','left_profile','right_profile','close_up','detail','additional']:['walk_video','walk_video_2'];
 var role=roles[index]||(type==='skin'?'additional':'walk_video');
 var prep=await VEUX_MODEL.api('/api/model/development-submissions',{method:'POST',body:JSON.stringify({organization_slug:'maison-de-veux',action:'prepare_upload',submission_id:submissionId,name:file.name,mime_type:file.type||'',size_bytes:file.size,file_role:role})});
 if(!prep||!prep.token)throw new Error('Secure upload token was not returned');
 var client=window.VEUX_SUPABASE_CLIENT;if(!client||!client.storage)throw new Error('Secure storage connection is not ready');
 var up=await client.storage.from(prep.bucket).uploadToSignedUrl(prep.path,prep.token,file,{contentType:file.type||undefined});if(up.error)throw up.error;
 var done=await VEUX_MODEL.api('/api/model/development-submissions',{method:'POST',body:JSON.stringify({organization_slug:'maison-de-veux',action:'finalize_upload',submission_id:submissionId,upload_session_id:prep.upload_session_id,file_role:role})});if(!done||done.verified!==true)throw new Error('Submission file was not verified');return done;
}
async function submitDevelopment(type){var input=document.getElementById(type==='skin'?'v1699-skin-files':'v1699-walk-files'),note=(document.getElementById(type==='skin'?'v1699-skin-note':'v1699-walk-note')||{}).value||'',files=Array.from(input&&input.files||[]),button=document.getElementById(type==='skin'?'v1699-skin-submit':'v1699-walk-submit');if(!files.length)return window.toast(type==='skin'?'Choose at least one skin photo':'Choose a model walk video');if(type==='walk'&&files.length>2)return window.toast('Upload up to 2 walk videos per submission');if(type==='skin'&&files.length>6)return window.toast('Upload up to 6 skin photos per submission');var created=null;try{if(button){button.disabled=true;button.textContent='Creating Submission…';}created=await VEUX_MODEL.api('/api/model/development-submissions',{method:'POST',body:JSON.stringify({organization_slug:'maison-de-veux',action:'create',submission_type:type,model_note:note,timezone:Intl.DateTimeFormat().resolvedOptions().timeZone})});if(!created||created.verified!==true||!created.submission)throw new Error('Submission record was not verified');for(var i=0;i<files.length;i++){if(button)button.textContent='Uploading '+(i+1)+' / '+files.length+'…';await uploadDevelopmentFile(created.submission.id,type,files[i],i);}window.toast(type==='skin'?'Skin check submitted for agency review':'Model walk submitted for agency review');await VEUX_MODEL.refresh();navTo('submissions',{skipPortalStack:true,historyMode:'replace'});}catch(e){window.toast('Submission failed: '+(e.message||e));if(button){button.disabled=false;button.textContent=type==='skin'?'Submit Skin Check':'Submit Model Walk';}}}
async function withdrawDevelopment(id){if(!id||!confirm('Withdraw this submission from agency review?'))return;try{await VEUX_MODEL.api('/api/model/development-submissions',{method:'POST',body:JSON.stringify({organization_slug:'maison-de-veux',action:'withdraw',submission_id:id})});window.toast('Submission withdrawn');await VEUX_MODEL.refresh();navTo('submissions',{skipPortalStack:true,historyMode:'replace'});}catch(e){window.toast('Could not withdraw submission: '+(e.message||e));}}

