var MODEL_NAV_STATE_KEY='veux-model-nav-state-v1',MODEL_NAV_STACK_KEY='veux-model-nav-stack-v1';
function modelNavRead(key,fallback){try{var raw=sessionStorage.getItem(key);return raw?JSON.parse(raw):fallback;}catch(_e){return fallback;}}
function modelNavWrite(key,value){try{sessionStorage.setItem(key,JSON.stringify(value));}catch(_e){}}
function modelNavState(page){return {veuxPortal:'model',page:page||S.page||'overview',thread:S.thread||null,calendarView:S.calendarView||'agenda',calendarDate:S.calendarDate||null};}
function modelApplyNavState(st){if(!st)return;if(st.thread)S.thread=st.thread;if(st.calendarView)S.calendarView=st.calendarView;if(st.calendarDate)S.calendarDate=st.calendarDate;}
function modelPushPrevious(next){var prev=modelNavRead(MODEL_NAV_STATE_KEY,null);if(!prev||!prev.page||prev.page===next)return;var stack=modelNavRead(MODEL_NAV_STACK_KEY,[]);if(!Array.isArray(stack))stack=[];var tail=stack[stack.length-1];if(!tail||tail.page!==prev.page||tail.thread!==prev.thread)stack.push(prev);if(stack.length>40)stack=stack.slice(-40);modelNavWrite(MODEL_NAV_STACK_KEY,stack);}
window.portalBack=function(){var stack=modelNavRead(MODEL_NAV_STACK_KEY,[]);if(!Array.isArray(stack))stack=[];var target=stack.pop()||{veuxPortal:'model',page:'overview'};modelNavWrite(MODEL_NAV_STACK_KEY,stack);modelApplyNavState(target);return navTo(target.page||'overview',{skipPortalStack:true,historyMode:'replace',restoreState:target});};
function navTo(p,opts){opts=opts||{};if(!DIRECT.has(p))p='overview';if(opts.restoreState)modelApplyNavState(opts.restoreState);if(!opts.skipPortalStack)modelPushPrevious(p);var pm=document.getElementById('pm');if(!pm)return;document.querySelectorAll('#pm .panel').forEach(function(x){x.classList.remove('on');});var el=document.getElementById('p-'+p);if(!el){el=document.createElement('div');el.id='p-'+p;el.className='panel';pm.appendChild(el);}el.classList.add('on');S.page=p;window._currentPage=p;var saved=modelNavState(p);modelNavWrite(MODEL_NAV_STATE_KEY,saved);try{var url=location.pathname+location.search+location.hash;if(opts.historyMode==='replace'||!history.state||history.state.veuxPortal!=='model')history.replaceState(saved,document.title,url);else if(!opts.fromPopState)history.pushState(saved,document.title,url);}catch(_e){}syncNotificationBadge();setActive(p);closeMobMore();if(typeof window.closeSB==='function')window.closeSB();if(R[p])R[p](el);else el.innerHTML='<div class="v15m-page">'+pageHead('MODEL PORTAL','Page unavailable','This compatibility page has not yet moved into first-class Model Portal rendering.')+'</div>';pm.scrollTop=0;}
function launch(){var b=boot(),u=b.current_user||{},x=m(),name=x.display_name||u.email||'Model',role='Model · '+((arr(x.market_assignments)[0]||{}).markets||{}).name||'Maison de Veux',av=document.getElementById('tbAv'),nm=document.getElementById('tbName'),rl=document.getElementById('tbRole'),app=document.getElementById('app');if(app){app.style.display='block';app.classList.add('on');}if(av)av.textContent=name.split(/\s+/).slice(0,2).map(function(z){return z[0]||'';}).join('').toUpperCase();if(nm)nm.textContent=name;if(rl)rl.textContent=role;var mark=document.querySelector('.tb-mark'),tag=document.querySelector('.tb-tag');if(mark)mark.innerHTML='VEUX DESK';if(tag)tag.textContent='MODEL PORTAL';buildNav();syncNotificationBadge();var restored=modelNavRead(MODEL_NAV_STATE_KEY,null);if(restored&&!DIRECT.has(restored.page))restored=null;if(restored)modelApplyNavState(restored);navTo(restored&&restored.page||S.page||'overview',{skipPortalStack:true,historyMode:'replace',restoreState:restored});initAssistantWidget();installModelMessageAlerts();window.dispatchEvent(new CustomEvent('veux:model-v16-ready',{detail:{version:'16.9.66',direct:Array.from(DIRECT),selfService:true,synchronizedReviews:true,threeWaySync:true,developmentSubmissions:true}}));}
