function closeSB(){var s=document.getElementById('sidenav'),o=document.getElementById('sb-ov');if(s)s.classList.remove('open');if(o)o.classList.remove('show');}function toggleSB(){var s=document.getElementById('sidenav'),o=document.getElementById('sb-ov');if(!s)return;var on=!s.classList.contains('open');s.classList.toggle('open',on);if(o)o.classList.toggle('show',on);}
