var _v15ReturnRefreshAt=0;function v15ReturnRefresh(){var now=Date.now();if(now-_v15ReturnRefreshAt<4000)return;var app=document.getElementById('app');if(!app||!app.classList.contains('on'))return;if(document.visibilityState&&document.visibilityState==='hidden')return;_v15ReturnRefreshAt=now;try{if(window.VEUX_MODEL&&VEUX_MODEL.refresh)VEUX_MODEL.refresh();}catch(_e){}}window.addEventListener('online',v15ReturnRefresh);window.addEventListener('focus',v15ReturnRefresh);document.addEventListener('visibilitychange',function(){if(document.visibilityState==='visible')v15ReturnRefresh();});
